UNOBTAINABLE = {
    "command_block", "chain_command_block", "repeating_command_block",
    "bedrock", "spawner", "barrier", "light", "structure_block",
    "structure_void", "jigsaw", "debug_stick", "command_block_minecart",
    "end_portal", "end_gateway", "nether_portal", "reinforced_deepslate",
}
