# ── 常用查询辅助 ────────────────────────────────────────────────

def recipe(item_id):
    """查配方（按物品 id 如 minecraft:oak_planks），返回 {materials, grid, yield, desc} 或 None。"""
    return RECIPES.get(item_id)


def is_unobtainable(item_id):
    """物品是否不可获取（命令方块/基岩等）。支持 minecraft:xxx 或裸名 xxx。"""
    if item_id in UNOBTAINABLE_FULL:
        return True
    if item_id.startswith("minecraft:") and item_id[len("minecraft:"):] in UNOBTAINABLE:
        return True
    if item_id in UNOBTAINABLE:
        return True
    return False


def needs_workbench(item_id) -> bool:
    """该配方是否需要工作台（3x3）。"""
    r = RECIPES.get(item_id)
    return bool(r and r["grid"] == "3x3")


def material_suffix(category) -> str:
    """材料类别 → 背包匹配后缀（_log/_planks/...）。"""
    m = MATERIAL_CATEGORIES.get(category)
    return m["suffix"] if m else category


def expand_material(category, state) -> str:
    """材料类别 → craft 用具体 id：expand 固定值直接用；None 按背包里找到的具体物品展开。

    例：log 类别 → 找背包里第一个 *_log（oak_log）→ 木板配方 oak_planks；
        plank 类别 → 找背包里第一个 *_planks。
    """
    from ._util import iter_items  # 延迟导入避免包初始化顺序问题
    m = MATERIAL_CATEGORIES.get(category)
    if m is None:
        return category
    if m["expand"]:
        return m["expand"]
    # 需要按背包展开：找到第一个匹配后缀的具体物品 id
    for entry in iter_items(state):
        iid = entry.get("id", "")
        if iid.endswith(m["suffix"]) and not iid.startswith("stripped_"):
            return iid
    return None
